86:       this.scrollLeft = x.left !== undefined ? x.left : (this.scrollLeft || 0);
87:       this.scrollTop = x.top !== undefined ? x.top : (this.scrollTop || 0);
88:       this._lastScrollBehavior = x.behavior || 'auto';
