const { window } = dom;

// Install layout mocks
window.Element.prototype.getBoundingClientRect = function() {
  const id = this.id;
  if (id === 'hero-play-btn') return { left: 96, top: 460, width: 180, height: 56, right: 276, bottom: 516 };
  if (id === 'hero-details-btn') return { left: 292, top: 460, width: 140, height: 56, right: 432, bottom: 516 };
  if (id === 'details-play-btn') return { left: 96, top: 450, width: 180, height: 56, right: 276, bottom: 506 };
  if (this.classList.contains('card-poster')) {
    const idx = Array.from(this.parentElement.children).indexOf(this);
    return { left: 96 + idx * 240, top: 600, width: 220, height: 330, right: 316 + idx * 240, bottom: 930 };
  }
  return { left: 100, top: 100, width: 100, height: 50, right: 200, bottom: 150 };
};
window.Element.prototype.scrollTo = function() {};

const navCode = fs.readFileSync('app/js/navigation.js', 'utf8');
const appCode = fs.readFileSync('app/js/app.js', 'utf8');
window.eval(navCode);
window.eval(appCode);

const app = window.CinejoyApp;
const nav = window.SpatialNav;
app.init();

app.switchView('movies');
const moviesCards = window.document.querySelectorAll('#view-movies .card-poster');
nav.setFocus(moviesCards[4]);

// Open details and focus button
app.openDetails({ title: 'Test', year: '2024' });
const detailsPlay = window.document.getElementById('details-play-btn');
nav.setFocus(detailsPlay);

// Press back
app.handleBackNavigation();

console.log('isNavigable(detailsPlay) after view is movies:', nav.isNavigable(detailsPlay));
